 resolution:'https://jcgm.bipm.org/vim/en/4.14.html',
 calibration:'https://jcgm.bipm.org/vim/en/2.39.html',
 heat:'https://openstax.org/books/university-physics-volume-2/pages/1-6-mechanisms-of-heat-transfer',
